from pyspark.sql import functions as F, Window

def run(spark, tables):
    policy = tables['policy']
    
    # Filter young drivers
    young_drivers = policy.filter(policy['DrivAge'] < 25).select('IDpol', 'DrivAge', F.lit(1).alias('Segment'))
    
    # Filter senior drivers
    senior_drivers = policy.filter(policy['DrivAge'] >= 70).select('IDpol', 'DrivAge', F.lit(2).alias('Segment'))
    
    # Union the results
    result = young_drivers.union(senior_drivers)
    
    return result
